const body = $input.first().json.body || {};
const conversation = body.conversation || {};
const meta = conversation.meta || {};
const sender = meta.sender || body.sender || {};
const contentAttrs = body.content_attributes || body.message?.content_attributes || {};
const customAttrs = conversation.custom_attributes || {};

function submittedEntries(attrs) {
  const submitted = attrs.submitted_values || attrs.submittedValues || [];
  if (Array.isArray(submitted)) return submitted;
  if (submitted && typeof submitted === 'object') return Object.entries(submitted).map(([name, value]) => ({ name, value }));
  return submitted ? [{ value: submitted }] : [];
}

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { return null; }
}

function objectValue(value) {
  const parsed = parseMaybeJson(value);
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
  return parsed;
}

function normalizeKnownValues(...values) {
  const known = {};
  for (const value of values) {
    const object = objectValue(value);
    for (const [key, raw] of Object.entries(object)) {
      const text = String(raw ?? '').trim();
      if (key && text) known[key] = text;
    }
  }
  return known;
}

function normalizeAttachmentRef(value) {
  if (!value || typeof value !== 'object') return null;
  return {
    id: value.id || value.attachment_id || value.blob_id || value.file_id || null,
    message_id: value.message_id || value.messageId || null,
    file_type: value.file_type || value.fileType || value.type || null,
    extension: value.extension || value.file_extension || null,
    content_type: value.content_type || value.mime_type || value.mimeType || null,
    file_size: value.file_size || value.fileSize || value.size || null,
    filename: value.filename || value.file_name || value.name || null,
    data_url: value.data_url || value.url || value.download_url || value.thumb_url || null
  };
}

function refsFromContentAttributes(attrs) {
  const refs = [];
  for (const key of ['attachment_refs', 'attachmentRefs', '_attachment_refs']) {
    const value = parseMaybeJson(attrs[key]);
    if (!value) continue;
    const items = Array.isArray(value) ? value : [value];
    for (const item of items) {
      const ref = normalizeAttachmentRef(item);
      if (ref) refs.push(ref);
    }
  }
  return refs;
}

function refsFromSubmittedValues(values) {
  const refs = [];
  for (const entry of values || []) {
    if (!entry || typeof entry !== 'object') continue;
    const key = entry.name || entry.id || entry.key;
    if (key !== '_attachment_refs') continue;
    const value = parseMaybeJson(entry.value ?? entry.answer ?? entry.text);
    const items = Array.isArray(value) ? value : [value];
    for (const item of items) {
      const ref = normalizeAttachmentRef(item);
      if (ref) refs.push(ref);
    }
  }
  return refs;
}

function collectRawAttachments(...sources) {
  const refs = [];
  for (const source of sources) {
    const items = Array.isArray(source) ? source : [];
    for (const item of items) {
      const ref = normalizeAttachmentRef(item);
      if (ref) refs.push(ref);
    }
  }
  return refs;
}

function mergeAttachmentRefs(...groups) {
  const seen = new Set();
  const merged = [];
  for (const group of groups) {
    for (const item of Array.isArray(group) ? group : []) {
      const ref = normalizeAttachmentRef(item);
      if (!ref) continue;
      const key = [ref.id, ref.message_id, ref.filename, ref.file_size, ref.data_url].map((part) => String(part || '')).join('|');
      if (seen.has(key)) continue;
      seen.add(key);
      merged.push(ref);
    }
  }
  return merged;
}

function isIncomingMessageType(value) {
  return value === 0 || value === '0' || String(value || '').toLowerCase() === 'incoming';
}

const event = body.event || '';
const messageType = body.message_type ?? body.message?.message_type ?? '';
const status = conversation.status || '';
const content = String(body.content || body.message?.content || '').trim();
const submittedValues = submittedEntries(contentAttrs);
const lastConversationMessage = Array.isArray(conversation.messages)
  ? (conversation.messages.find((item) => String(item.id) === String(body.id || body.message?.id)) || conversation.messages[0] || {})
  : {};
const attachmentRefs = mergeAttachmentRefs(
  refsFromContentAttributes(contentAttrs),
  refsFromSubmittedValues(submittedValues),
  collectRawAttachments(body.attachments, body.message?.attachments, lastConversationMessage.attachments)
);
const hasAttachments = attachmentRefs.length > 0;
const knownValues = normalizeKnownValues(
  contentAttrs.known_values,
  contentAttrs.knownValues,
  customAttrs.escalation_known_fields,
  customAttrs.escalationKnownFields
);

let route = 'ignore';
if (event === 'message_created' && isIncomingMessageType(messageType) && status === 'pending' && content) {
  route = 'user_message';
} else if (event === 'message_updated' && body.content_type === 'form' && submittedValues.length > 0 && status === 'pending') {
  route = 'form_submitted';
}

return [{ json: {
  route,
  accountId: (body.account && body.account.id) || conversation.account_id || null,
  conversationId: conversation.id || null,
  content,
  contactName: sender.name || 'Player',
  submittedValues: submittedValues.length ? submittedValues : null,
  attachmentRefs,
  hasAttachments,
  knownValues,
  customAttributes: customAttrs,
  category: customAttrs.escalation_category || 'other',
  summary: customAttrs.escalation_summary || '',
  rewardSource: customAttrs.reward_source || customAttrs.rewardSource || '',
  status
} }];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "reply",
        "escalate",
        "handoff"
      ]
    },
    "reply": {
      "type": "string",
      "description": "Plain-text message shown to the player. Do not use Markdown syntax. Do not use inline numbered lists. Use line breaks for separate checks. Do not repeat the same question if the latest player message answers it; acknowledge the answer and move to the next step. Never mention retrieval, retrieved information, search results, knowledge base, FAQ search, or that nothing was found. If the player asks a clearly unrelated question, do not answer it; redirect to Pro Golf support only. Plain text only: no Markdown syntax, no bullet symbols, no bold markers. For club/equipment or gameplay optimization questions, do not include improvement advice unless the exact causal effect appears in retrieved FAQ content. Never say upgrades improve shot distance, spin, accuracy, precision, control, or performance unless explicitly grounded."
    },
    "category": {
      "type": "string",
      "enum": [
        "purchase_payment",
        "withdrawal",
        "account",
        "technical_bug",
        "gameplay_tournament",
        "ban_appeal",
        "player_report",
        "other",
        "reward"
      ],
      "description": "Support category. Use other for greetings or clearly unrelated messages outside Pro Golf support."
    },
    "summary": {
      "type": "string",
      "description": "Internal summary for the human support agent"
    },
    "reward_source": {
      "type": "string",
      "enum": [
        "",
        "unknown",
        "tournament",
        "daily_bonus",
        "golf_pass",
        "topshot",
        "loot_bag",
        "balance_reward"
      ],
      "description": "Reward source when category is reward. Use unknown if unclear."
    },
    "collected_fields": {
      "type": "object",
      "additionalProperties": {
        "type": "string"
      },
      "description": "Explicit player-provided values for already answered form fields, keyed by the exact field names in the escalation field catalog. Use only known values and preserve relative dates such as yesterday verbatim."
    },
    "handoff_override_reason": {
      "type": "string",
      "enum": [
        "",
        "critical",
        "explicit_human_request",
        "post_form_followup"
      ],
      "description": "Reason an incomplete case may bypass the form. Empty unless one of the documented forced-handoff cases applies."
    }
  },
  "required": [
    "action",
    "reply"
  ]
}

