const qaItem = $input.first().json;
const qaOutput = qaItem.output || {};
const supportItem = $('Support Agent').first().json || {};
const supportOutput = supportItem.output || {};

function cleanAction(value) {
  const action = String(value || '').trim();
  return ['reply', 'escalate', 'handoff'].includes(action) ? action : 'reply';
}

function objectValue(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

const action = cleanAction(supportOutput.action || qaOutput.action);
const qaStatus = qaOutput.qa_status || qaOutput.qaStatus || 'pass_through';
const supportReply = String(supportOutput.reply || '').trim();
const qaReply = String(qaOutput.reply || '').trim();
const reply = action === 'reply'
  ? (qaReply || supportReply)
  : (supportReply || qaReply || 'I will collect a few details so our support team can help.');

return [{
  json: {
    ...qaItem,
    output: {
      ...qaOutput,
      action,
      reply,
      category: supportOutput.category || qaOutput.category || 'other',
      summary: supportOutput.summary || qaOutput.summary || '',
      reward_source: supportOutput.reward_source || supportOutput.rewardSource || qaOutput.reward_source || qaOutput.rewardSource || '',
      collected_fields: objectValue(supportOutput.collected_fields || supportOutput.collectedFields || qaOutput.collected_fields || qaOutput.collectedFields),
      handoff_override_reason: supportOutput.handoff_override_reason || supportOutput.handoffOverrideReason || qaOutput.handoff_override_reason || qaOutput.handoffOverrideReason || '',
      qa_status: qaStatus,
      qa_issues: Array.isArray(qaOutput.qa_issues) ? qaOutput.qa_issues : [],
      qa_faq_ids: Array.isArray(qaOutput.qa_faq_ids) ? qaOutput.qa_faq_ids : []
    },
    support_output: supportOutput,
    qa_output: qaOutput
  }
}];

const ev = $('Extract Event').first().json;
const item = $input.first().json;
const out = { ...(item.output || {}) };

function lower(value) { return String(value || '').trim().toLowerCase(); }
function combinedText() { return [ev.content, out.reply, out.summary].map(lower).join(' '); }
function includesAny(text, words) { return words.some((word) => text.includes(word)); }

const categories = ['purchase_payment','withdrawal','account','technical_bug','gameplay_tournament','ban_appeal','player_report','other','reward'];
let category = lower(out.category);
if (!categories.includes(category)) category = 'other';

const text = combinedText();
const playerReport = /\b(cheat(er|ing)?|hacker|hack(ing|ed)?|unfair|harass(ment|ing|ed)?|abusive?|report(ing)?\s+(a\s+)?player|disruptive|toxic)\b/i.test(text);
if (playerReport && ['gameplay_tournament', 'other'].includes(category)) category = 'player_report';
const tournamentReward = /\b(tournament|championship|leaderboard|placement|placed|prize pool|cash tournament|last tournament)\b/i.test(text)
  && /\b(missing|missed|didn'?t get|did not get|not received|not credited|never received|cash|winnings?|prize|reward|payout)\b/i.test(text);
const explicitWithdrawal = /\b(withdrawal|withdraw|withdrawing|cash\s*out|cashout|paypal|reference\s+number|bank\s+transfer|payment\s+processor)\b/i.test(lower(ev.content).replace(/\bwithdrawable\s+funds?\b/g, ' '));
if (category === 'withdrawal' && tournamentReward && !explicitWithdrawal) category = 'reward';

let rewardSource = lower(out.reward_source || out.rewardSource);
if (category === 'reward' && (!rewardSource || rewardSource === 'unknown')) {
  if (includesAny(text, ['tournament','championship','leaderboard','prize pool'])) rewardSource = 'tournament';
  else if (includesAny(text, ['daily bonus','daily login','login bonus'])) rewardSource = 'daily_bonus';
  else if (includesAny(text, ['golf pass','pass reward'])) rewardSource = 'golf_pass';
  else if (includesAny(text, ['topshot','top shot'])) rewardSource = 'topshot';
  else if (includesAny(text, ['loot bag','lootbag','loot ladder'])) rewardSource = 'loot_bag';
  else if (includesAny(text, ['bonus cash','cash reward','wallet','balance','money'])) rewardSource = 'balance_reward';
  else rewardSource = 'unknown';
}
if (category !== 'reward') rewardSource = '';

out.category = category;
out.reward_source = rewardSource;
return [{ json: { ...item, output: out } }];

const ev = $('Extract Event').first().json;
const decision = $('Normalize Escalation Lookup').first().json;
const out = { ...(decision.output || {}) };
const requirements = $input.first().json || {};

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { return null; }
}
function objectValue(value) {
  const parsed = parseMaybeJson(value);
  return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
}
function clean(value) { return String(value ?? '').replace(/\s+/g, ' ').trim(); }
function usable(value) {
  const text = clean(value);
  return text && !/^(unknown|not sure|not provided|n\/a|na|none|null|undefined)$/i.test(text);
}

const allowed = new Set(Array.isArray(requirements.required_fields) ? requirements.required_fields : []);
const prior = {
  ...objectValue(ev.customAttributes?.escalation_known_fields),
  ...objectValue(ev.knownValues)
};
const current = objectValue(out.collected_fields || out.collectedFields);
const collected = {};
for (const [name, value] of Object.entries({ ...prior, ...current })) {
  if (allowed.has(name) && usable(value)) collected[name] = clean(value);
}
const missing = [...allowed].filter((name) => !Object.prototype.hasOwnProperty.call(collected, name));

const explicitHuman = /\b(human|live agent|support agent|representative|real person|someone from support|speak to someone|talk to someone)\b/i.test(String(ev.content || ''));
const priorForm = Boolean(ev.customAttributes?.escalation_missing_fields || ev.customAttributes?.escalation_omitted_fields);
const requestedOverride = String(out.handoff_override_reason || '').trim();
let overrideReason = '';
if (requestedOverride === 'critical') overrideReason = 'critical';
else if (explicitHuman || requestedOverride === 'explicit_human_request') overrideReason = 'explicit_human_request';
else if (priorForm || requestedOverride === 'post_form_followup') overrideReason = 'post_form_followup';

const action = overrideReason || missing.length === 0 ? 'handoff' : 'escalate';
if (action === 'handoff') {
  out.reply = 'Thanks. I am connecting you with our support team. A human agent will get back to you shortly.';
}

return [{ json: {
  ...decision,
  output: {
    ...out,
    action,
    category: requirements.category || out.category || 'other',
    reward_source: requirements.reward_source || '',
    collected_fields: collected,
    handoff_override_reason: overrideReason
  },
  requirements,
  missing_fields: missing,
  omitted_fields: Object.keys(collected)
} }];

const ev = $('Extract Event').first().json;
const item = $input.first().json;
const out = item.output || {};
const requirements = item.requirements || {};
const category = out.category || requirements.category || 'other';
const rewardSource = out.reward_source || requirements.reward_source || '';
const summary = out.summary || '';
const collectedFields = out.collected_fields && typeof out.collected_fields === 'object' ? out.collected_fields : {};
const missingFields = Array.isArray(item.missing_fields) ? item.missing_fields : [];
const missingSet = new Set(missingFields);
const items = Array.isArray(requirements.items) ? requirements.items : [];
function recentTournamentIds(attrs) {
  const values = [];
  const add = (value) => {
    for (const part of String(value || '').split(/[,|]/)) {
      const id = part.trim();
      if (id && !values.includes(id)) values.push(id);
    }
  };
  add(attrs.current_tournament_id || attrs.currentTournamentId || attrs.tournament_id || attrs.tournamentId);
  add(attrs.last_3_tournament_ids || attrs.last3TournamentIds || attrs.last_tournament_ids || attrs.recentTournamentIds);
  return values.slice(0, 3);
}

function normalizedOption(option) {
  if (typeof option === 'string') return { label: option, value: option };
  const value = option && typeof option === 'object' ? option : {};
  return {
    label: String(value.label || value.text || value.value || value.id || ''),
    value: String(value.value || value.id || value.text || value.label || '')
  };
}

const tournamentIds = recentTournamentIds(ev.customAttributes || {});
function expandDynamicOptions(field) {
  if (field?.type !== 'select' || !Array.isArray(field.options)) return field;
  const options = [];
  for (const rawOption of field.options) {
    const option = normalizedOption(rawOption);
    const token = String(option.label || option.value).trim().toLowerCase();
    if (token === 'tournamentids') {
      for (const tournamentId of tournamentIds) options.push({ label: tournamentId, value: tournamentId });
    } else if (option.label || option.value) {
      options.push(option);
    }
  }
  return { ...field, options };
}

const visibleItems = items
  .filter((field) => missingSet.has(field.name))
  .map(expandDynamicOptions);
const omittedFields = Object.keys(collectedFields);
const skipForm = visibleItems.length === 0;

function conciseLeadIn(value, originalReply) {
  const reply = String(originalReply || '').replace(/\s+/g, ' ').trim();
  const faqLike = /\b(FAQ|withdrawals? can|business days|processing fee|minimum amount|bonus cash|prize pool|coins|tickets|golf pass points|support team at|provide as much detail|confirmation email|restart|internet connection|technical issue)\b/i.test(reply);
  if (reply && reply.length <= 180 && !faqLike) return reply;
  const leadIns = {
    purchase_payment: 'I will collect a few details so our support team can check your payment issue.',
    withdrawal: 'I will collect a few details so our support team can check your withdrawal.',
    account: 'I will collect a few details so our support team can help with your account.',
    technical_bug: 'I will collect a few details so our support team can look into this issue.',
    gameplay_tournament: 'I will collect a few details so our support team can review the tournament issue.',
    player_report: 'I will collect a few details so our support team can review this player report.',
    ban_appeal: 'I will collect a few details so our support team can review your restriction.',
    reward: 'I will collect a few details so our support team can check the missing reward.',
    other: 'I will collect a few details so our support team can help.'
  };
  return leadIns[value] || leadIns.other;
}

const content = skipForm
  ? 'Thanks. I am connecting you with our support team. A human agent will get back to you shortly.'
  : conciseLeadIn(category, out.reply);
const existingAttrs = ev.customAttributes && typeof ev.customAttributes === 'object' && !Array.isArray(ev.customAttributes) ? ev.customAttributes : {};
const customAttributes = {
  ...existingAttrs,
  escalation_category: category,
  escalation_summary: summary,
  escalation_known_fields: JSON.stringify(collectedFields),
  escalation_omitted_fields: JSON.stringify(omittedFields),
  escalation_missing_fields: JSON.stringify(missingFields)
};
if (category === 'reward') customAttributes.reward_source = rewardSource || 'unknown';

return [{ json: {
  output: { ...out, action: skipForm ? 'handoff' : 'escalate', reply: content },
  formBody: {
    content,
    content_type: 'form',
    content_attributes: {
      items: visibleItems,
      attachment_config: requirements.attachment_config || { enabled: true, accept: ['image/*','video/*'], max_files: 3, optional: true },
      known_values: collectedFields
    },
    private: false
  },
  attrsBody: { custom_attributes: customAttributes },
  accountId: ev.accountId,
  conversationId: ev.conversationId,
  rewardSource,
  knownValues: collectedFields,
  omittedFields,
  missingFields,
  skipForm
} }];

const ev = $('Extract Event').first().json;
const item = $input.first().json;
let category, noteContent, confirmText;

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { return null; }
}

function objectValue(value) {
  const parsed = parseMaybeJson(value);
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
  return parsed;
}

function getBuildOutput() {
  try { return $('Build Escalation Form').first().json || {}; } catch (e) { return {}; }
}

function attachmentSize(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return '';
  return String(n) + ' bytes';
}

function formatAttachments(attachments) {
  const refs = Array.isArray(attachments) ? attachments : [];
  if (!refs.length) return '';
  const lines = refs.map((attachment, index) => {
    const parts = ['attachment_' + (index + 1)];
    const filename = clean(attachment.filename || attachment.file_name || attachment.name);
    const fileType = clean(attachment.file_type || attachment.fileType || attachment.type);
    const contentType = clean(attachment.content_type || attachment.mime_type || attachment.mimeType);
    const size = attachmentSize(attachment.file_size || attachment.fileSize || attachment.size);
    const messageId = clean(attachment.message_id || attachment.messageId);
    const attachmentId = clean(attachment.id || attachment.attachment_id || attachment.blob_id || attachment.file_id);
    if (filename) parts.push('filename=' + filename);
    if (fileType) parts.push('file_type=' + fileType);
    if (contentType) parts.push('content_type=' + contentType);
    if (size) parts.push('size=' + size);
    if (messageId) parts.push('message_id=' + messageId);
    if (attachmentId) parts.push('attachment_id=' + attachmentId);
    return '- ' + parts.join(' | ');
  });
  return '\n\n**Attachments (' + refs.length + '):**\n' + lines.join('\n');
}

function formValueLine(value) {
  const label = value.label || value.title || value.name || 'Response';
  return '- **' + label + '**: ' + (value.value ?? value.answer ?? value.text ?? '');
}

function formatKnownFields(fields) {
  const object = objectValue(fields);
  const entries = Object.entries(object).filter(([, value]) => clean(value));
  if (!entries.length) return '';
  return '\n\n**Known from chat:**\n' + entries.map(([key, value]) => '- **' + key + '**: ' + clean(value)).join('\n');
}

function appendTicketId(message) {
  const ticketId = clean(ev.conversationId);
  const text = String(message || '').trim();
  if (!ticketId || /ticket\s*id\s*:/i.test(text)) return text;
  return text + '\n\nTicket ID: #' + ticketId;
}

const buildOutput = getBuildOutput();
const effectiveItem = item.output ? item : (buildOutput.output ? buildOutput : item);
const attachmentSection = formatAttachments(ev.attachmentRefs || ev.attachments || []);

if (ev.route === 'form_submitted') {
  category = ev.category || 'other';
  const sourceLine = category === 'reward' && ev.rewardSource ? '\n**Reward source:** ' + ev.rewardSource + '\n' : '';
  const knownSection = formatKnownFields(ev.knownValues || ev.customAttributes?.escalation_known_fields);
  const lines = (ev.submittedValues || [])
    .filter((v) => v && typeof v === 'object' && (v.name || v.id || v.key) !== '_attachment_refs')
    .map(formValueLine);
  noteContent = '**Bot escalation - ' + category + '**' + sourceLine + '\n' + (ev.summary || 'No summary recorded.') + knownSection + '\n\n**Form details:**\n' + (lines.length ? lines.join('\n') : 'No submitted values saved.') + attachmentSection;
  confirmText = 'Thanks! Your details have been sent to our support team. A human agent will get back to you shortly.';
} else {
  const out = effectiveItem.output || {};
  category = out.category || 'other';
  const rewardSource = out.reward_source || out.rewardSource || '';
  const sourceLine = category === 'reward' && rewardSource ? '\n**Reward source:** ' + rewardSource + '\n' : '';
  const knownSection = formatKnownFields(out.collected_fields || effectiveItem.knownValues || ev.knownValues || ev.customAttributes?.escalation_known_fields);
  noteContent = '**Bot escalation - ' + category + '** (no form, details collected in chat)' + sourceLine + '\n' + (out.summary || 'Player requested human assistance.') + knownSection + attachmentSection;
  confirmText = out.reply || 'I am connecting you with our support team. A human agent will get back to you shortly.';
}

confirmText = appendTicketId(confirmText);

return [{ json: { accountId: ev.accountId, conversationId: ev.conversationId, category, noteContent, confirmText } }];

const executionId = String($execution.id || 'unknown');

return [{
  json: {
    output: {
      action: 'handoff',
      reply: 'I’m connecting you with our support team. A human agent will get back to you shortly.',
      category: 'other',
      summary:
        'Automated support dependency failed before a safe response could be generated. ' +
        'Execution ID: ' + executionId,
      reward_source: '',
      collected_fields: {},
      handoff_override_reason: 'critical'
    }
  }
}];
